CREATE OR REPLACE FUNCTION public.admin_unlink_loyalty_by_profile(p_profile_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
declare
  v_role text;
  v_loyalty_id uuid;
begin
  select role into v_role
  from public.profiles
  where id = auth.uid();

  if v_role is null or v_role not in ('admin', 'super_admin') then
    raise exception 'Access denied';
  end if;

  select loyalty_account_id into v_loyalty_id
  from public.profiles
  where id = p_profile_id;

  update public.profiles
    set loyalty_account_id = null
  where id = p_profile_id;

  update public.loyalty_members
    set user_id = null
  where user_id = p_profile_id;

  -- also clear that specific loyalty record if it was linked
  if v_loyalty_id is not null then
    update public.loyalty_members
      set user_id = null
    where id = v_loyalty_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.auto_create_welcome_voucher_for_member()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.user_id is null then
    return new;
  end if;

  if tg_op = 'INSERT' then
    if exists (
      select 1 from public.voucher_campaigns
       where code = 'WELCOME-VOUCHER'
         and is_active = true
         and auto_create_on_signup = true
         and (starts_at is null or starts_at <= now())
         and (ends_at is null or ends_at >= now())
    ) then
      perform public.create_welcome_voucher_if_needed(new.id);
    end if;
  elsif tg_op = 'UPDATE' then
    if old.user_id is distinct from new.user_id then
      if exists (
        select 1 from public.voucher_campaigns
         where code = 'WELCOME-VOUCHER'
           and is_active = true
           and auto_create_on_link = true
           and (starts_at is null or starts_at <= now())
           and (ends_at is null or ends_at >= now())
      ) then
        perform public.create_welcome_voucher_if_needed(new.id);
      end if;
    end if;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.award_loyalty_points_for_order(p_order_id uuid, p_member_id uuid, p_points numeric, p_sale_total numeric DEFAULT 0)
 RETURNS loyalty_members
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_member public.loyalty_members%rowtype;
  v_points numeric(12, 2) := round(greatest(coalesce(p_points, 0), 0)::numeric, 2);
  v_sale_total numeric(12, 2) := round(greatest(coalesce(p_sale_total, 0), 0)::numeric, 2);
  v_visit_stamp timestamptz := now();
begin
  if p_member_id is null then raise exception 'Loyalty member is required.'; end if;

  select * into v_member
  from public.loyalty_members
  where id = p_member_id
  for update;
  if not found then raise exception 'Loyalty member was not found.'; end if;
  if p_order_id is null or v_points <= 0 then return v_member; end if;

  select * into v_order
  from public.orders
  where id = p_order_id
  for update;
  if not found then raise exception 'Order was not found for loyalty award.'; end if;

  if coalesce(v_order.loyalty_points_awarded, 0) > 0
     or v_order.loyalty_points_awarded_at is not null then
    insert into public.loyalty_point_award_events (
      member_id, source_type, source_id, receipt_number, points_awarded,
      sale_total, points_balance_after, available_points_after, awarded_at
    ) values (
      p_member_id, 'order', p_order_id, v_order.receipt_number,
      coalesce(v_order.loyalty_points_awarded, v_points), v_sale_total,
      v_member."Points balance", v_member."Available points",
      coalesce(v_order.loyalty_points_awarded_at, v_visit_stamp)
    ) on conflict (source_type, source_id) do nothing;
    return v_member;
  end if;

  update public.loyalty_members
  set "Points balance" = round((coalesce("Points balance", 0) + v_points)::numeric, 2),
      "Available points" = round((coalesce("Available points", 0) + v_points)::numeric, 2),
      "Total visits" = coalesce("Total visits", 0) + 1,
      "Total spent" = round((coalesce("Total spent", 0) + v_sale_total)::numeric, 2),
      "First visit" = coalesce("First visit", v_visit_stamp::text),
      "Last visit" = v_visit_stamp::text
  where id = p_member_id
  returning * into v_member;

  update public.orders
  set loyalty_points_awarded = v_points,
      loyalty_points_awarded_at = v_visit_stamp,
      customer_id = p_member_id,
      loyalty_member_id = p_member_id,
      customer_name = v_member.customer_name
  where id = p_order_id
  returning * into v_order;

  insert into public.loyalty_point_award_events (
    member_id, source_type, source_id, receipt_number, points_awarded,
    sale_total, points_balance_after, available_points_after, awarded_at
  ) values (
    p_member_id, 'order', p_order_id, v_order.receipt_number, v_points,
    v_sale_total, v_member."Points balance", v_member."Available points", v_visit_stamp
  ) on conflict (source_type, source_id) do nothing;

  return v_member;
end;
$function$

CREATE OR REPLACE FUNCTION public.award_loyalty_points_for_web_order(p_web_order_id uuid, p_member_id uuid, p_points numeric, p_sale_total numeric DEFAULT 0)
 RETURNS loyalty_members
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_points numeric(12, 2) := round(greatest(coalesce(p_points, 0), 0)::numeric, 2);
  v_sale_total numeric(12, 2) := round(greatest(coalesce(p_sale_total, 0), 0)::numeric, 2);
  v_member public.loyalty_members%rowtype;
  v_web_order public.web_orders%rowtype;
  v_visit_stamp timestamptz := now();
begin
  if p_web_order_id is null then raise exception 'Web order id is required.'; end if;
  if p_member_id is null then raise exception 'Loyalty member id is required.'; end if;

  select * into v_member
  from public.loyalty_members
  where id = p_member_id
  for update;
  if not found then raise exception 'Loyalty member % was not found.', p_member_id; end if;

  select * into v_web_order
  from public.web_orders
  where id = p_web_order_id
  for update;
  if not found then raise exception 'Web order % was not found.', p_web_order_id; end if;

  if coalesce(v_web_order.loyalty_points_awarded, 0) > 0
     or v_web_order.loyalty_points_awarded_at is not null then
    insert into public.loyalty_point_award_events (
      member_id, source_type, source_id, receipt_number, points_awarded,
      sale_total, points_balance_after, available_points_after, awarded_at
    ) values (
      p_member_id, 'web_order', p_web_order_id,
      coalesce(v_web_order.receipt_number, 'WEB-' || upper(left(replace(p_web_order_id::text, '-', ''), 8))),
      coalesce(v_web_order.loyalty_points_awarded, v_points),
      coalesce(v_web_order.loyalty_sale_total, v_sale_total),
      v_member."Points balance", v_member."Available points",
      coalesce(v_web_order.loyalty_points_awarded_at, v_visit_stamp)
    ) on conflict (source_type, source_id) do nothing;
    return v_member;
  end if;

  if v_points <= 0 then return v_member; end if;

  update public.loyalty_members
  set "Points balance" = round((coalesce("Points balance", 0) + v_points)::numeric, 2),
      "Available points" = round((coalesce("Available points", 0) + v_points)::numeric, 2),
      "Total visits" = coalesce("Total visits", 0) + 1,
      "Total spent" = round((coalesce("Total spent", 0) + v_sale_total)::numeric, 2),
      "First visit" = coalesce("First visit", v_visit_stamp::text),
      "Last visit" = v_visit_stamp::text
  where id = p_member_id
  returning * into v_member;

  update public.web_orders
  set loyalty_member_id = p_member_id,
      loyalty_points_awarded = v_points,
      loyalty_points_awarded_at = v_visit_stamp,
      loyalty_sale_total = v_sale_total,
      customer_name = coalesce(customer_name, v_member.customer_name)
  where id = p_web_order_id
  returning * into v_web_order;

  insert into public.loyalty_point_award_events (
    member_id, source_type, source_id, receipt_number, points_awarded,
    sale_total, points_balance_after, available_points_after, awarded_at
  ) values (
    p_member_id, 'web_order', p_web_order_id,
    coalesce(v_web_order.receipt_number, 'WEB-' || upper(left(replace(p_web_order_id::text, '-', ''), 8))),
    v_points, v_sale_total, v_member."Points balance", v_member."Available points", v_visit_stamp
  ) on conflict (source_type, source_id) do nothing;

  return v_member;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_voucher_from_campaign(p_member_id uuid, p_campaign_code text)
 RETURNS TABLE(created integer, voucher_id uuid, code text, skipped text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  campaign_row public.voucher_campaigns%rowtype;
  member_exists boolean;
  existing_voucher_id uuid;
  next_reward_index integer;
  generated_code text;
  new_voucher_id uuid;
  issued_at_value timestamptz := now();
  expires_at_value timestamptz;
  try_count integer := 0;
begin
  if p_member_id is null or nullif(trim(coalesce(p_campaign_code, '')), '') is null then
    return query select 0, null::uuid, null::text, 'missing_input';
    return;
  end if;

  select exists(select 1 from public.loyalty_members where id = p_member_id)
    into member_exists;

  if not member_exists then
    return query select 0, null::uuid, null::text, 'member_not_found';
    return;
  end if;

  select vc.*
    into campaign_row
    from public.voucher_campaigns vc
   where upper(vc.code) = upper(trim(p_campaign_code))
     and vc.is_active = true
     and (vc.starts_at is null or vc.starts_at <= issued_at_value)
     and (vc.ends_at is null or vc.ends_at >= issued_at_value)
   order by vc.created_at desc
   limit 1;

  if campaign_row.id is null then
    return query select 0, null::uuid, null::text, 'campaign_inactive';
    return;
  end if;

  select v.id
    into existing_voucher_id
    from public.vouchers v
   where v.member_id = p_member_id
     and (
       v.campaign_id = campaign_row.id
       or upper(coalesce(v.campaign_code, '')) = upper(campaign_row.code)
       or (
         campaign_row.reward_type = 'welcome'
         and (
           coalesce(v.reward_type, '') = 'welcome'
           or upper(coalesce(v.code, '')) like 'WELCOME%'
           or lower(coalesce(v.reward_text, '')) like '%welcome voucher%'
         )
       )
     )
   limit 1;

  if existing_voucher_id is not null then
    return query select 0, existing_voucher_id, null::text, 'exists';
    return;
  end if;

  select coalesce(max(reward_index), 0) + 1
    into next_reward_index
    from public.vouchers
   where member_id = p_member_id;

  expires_at_value := issued_at_value + make_interval(days => campaign_row.validity_days);

  loop
    try_count := try_count + 1;
    generated_code := upper(campaign_row.voucher_prefix) || '-' || lpad((floor(random() * 10000))::int::text, 4, '0');
    exit when not exists(select 1 from public.vouchers v where v.code = generated_code) or try_count >= 25;
  end loop;

  if exists(select 1 from public.vouchers v where v.code = generated_code) then
    generated_code := upper(campaign_row.voucher_prefix) || '-' || replace(gen_random_uuid()::text, '-', '');
    generated_code := left(generated_code, 32);
  end if;

  insert into public.vouchers (
    member_id,
    reward_index,
    code,
    reward_text,
    issued_at,
    expires_at,
    status,
    reward_type,
    campaign_id,
    campaign_code
  )
  values (
    p_member_id,
    next_reward_index,
    generated_code,
    campaign_row.reward_text,
    issued_at_value,
    expires_at_value,
    'active',
    campaign_row.reward_type,
    campaign_row.id,
    campaign_row.code
  )
  returning id into new_voucher_id;

  return query select 1, new_voucher_id, generated_code, null::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.create_welcome_voucher_if_needed(p_member_id uuid)
 RETURNS TABLE(created integer, voucher_id uuid, code text, skipped text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  linked_user_id uuid;
begin
  select lm.user_id
    into linked_user_id
    from public.loyalty_members lm
   where lm.id = p_member_id;

  if p_member_id is null then
    return query select 0, null::uuid, null::text, 'missing_input';
    return;
  end if;

  if not found then
    return query select 0, null::uuid, null::text, 'member_not_found';
    return;
  end if;

  if linked_user_id is null then
    return query select 0, null::uuid, null::text, 'not_linked';
    return;
  end if;

  return query
    select *
      from public.create_voucher_from_campaign(p_member_id, 'WELCOME-VOUCHER');
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_vouchers_for_member(p_member_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_member record;
  v_available numeric := 0;
  v_existing_consumed numeric := 0;
  v_voucher_count integer := 0;
  v_created_count integer := 0;
  v_next_index integer := 0;
  v_inserted_id uuid;
begin
  perform public.expire_vouchers();

  select *
  into v_member
  from public.loyalty_members
  where id = p_member_id;

  if not found then
    return;
  end if;

  with marked as (
    update public.vouchers
    set
      points_consumed = 100,
      points_consumed_at = now()
    where member_id = p_member_id
      and coalesce(reward_type, 'points') = 'points'
      and status = 'active'
      and redeemed_at is null
      and points_consumed_at is null
    returning id
  )
  select coalesce(count(*) * 100, 0)
  into v_existing_consumed
  from marked;

  if v_existing_consumed > 0 then
    update public.loyalty_members
    set "Available points" = greatest(coalesce("Available points", 0) - v_existing_consumed, 0)
    where id = p_member_id;
  end if;

  select *
  into v_member
  from public.loyalty_members
  where id = p_member_id;

  v_available := coalesce(v_member."Available points", 0);
  v_voucher_count := floor(v_available / 100);

  if v_voucher_count <= 0 then
    return;
  end if;

  select coalesce(max(reward_index), 0)
  into v_next_index
  from public.vouchers
  where member_id = p_member_id;

  for i in 1..v_voucher_count loop
    v_next_index := v_next_index + 1;

    insert into public.vouchers (
      member_id,
      reward_index,
      code,
      reward_text,
      issued_at,
      expires_at,
      status,
      reward_type,
      points_consumed,
      points_consumed_at
    )
    values (
      p_member_id,
      v_next_index,
      'PTS100-' || v_next_index || '-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8)),
      'FREE 16oz Drink, Waffle, or Mini Donuts (100 Points Reward)',
      now(),
      now() + interval '90 days',
      'active',
      'points',
      100,
      now()
    )
    returning id into v_inserted_id;

    if v_inserted_id is not null then
      v_created_count := v_created_count + 1;
    end if;
  end loop;

  if v_created_count > 0 then
    update public.loyalty_members
    set "Available points" = greatest(coalesce("Available points", 0) - (v_created_count * 100), 0)
    where id = p_member_id;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.generate_birthday_vouchers()
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare
  m record;
  bday date;
  today date := current_date;
  start_date date;
  end_date date;
begin

  for m in
    select * from loyalty_members
    where "Note" is not null
  loop

    begin
      bday := to_date(m."Note", 'YYYY-Mon-DD');
    exception
      when others then
        continue;
    end;

    bday := make_date(
      extract(year from today)::int,
      extract(month from bday)::int,
      extract(day from bday)::int
    );

    start_date := bday - interval '2 days';
    end_date := bday + interval '2 days';

    if today = start_date then

      if not exists (
        select 1 from vouchers
        where member_id = m.id
        and reward_text = 'Birthday Reward'
        and date(issued_at) = today
      ) then

        insert into vouchers (
          member_id,
          reward_index,
          code,
          reward_text,
          issued_at,
          expires_at,
          status
        )
        values (
          m.id,
          1,  -- ✅ FIX HERE
          'BDAY' || floor(random()*100000)::text,
          '🎂 Birthday Free Drink or Waffle',
          now(),
          end_date,
          'active'
        );

      end if;

    end if;

  end loop;

end;
$function$

CREATE OR REPLACE FUNCTION public.generate_loyalty_customer_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.customer_code is null or btrim(new.customer_code) = '' then
    new.customer_code := public.next_loyalty_customer_code();
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.redeem_voucher(p_code text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_record RECORD;
BEGIN

  SELECT *
  INTO v_record
  FROM vouchers
  WHERE code = p_code;

  IF NOT FOUND THEN
    RETURN 'INVALID';
  END IF;

  IF v_record.status = 'redeemed' THEN
    RETURN 'ALREADY_USED';
  END IF;

  IF v_record.expires_at < NOW() THEN
    RETURN 'EXPIRED';
  END IF;

  UPDATE vouchers
  SET status = 'redeemed',
      redeemed_at = NOW()
  WHERE id = v_record.id;

  RETURN 'SUCCESS';

END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_loyalty_points_for_order(p_order_id uuid, p_member_id uuid, p_points numeric, p_sale_total numeric DEFAULT 0)
 RETURNS loyalty_members
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_order public.orders%rowtype;
  v_member public.loyalty_members%rowtype;
  v_requested_points numeric(12, 2) := round(greatest(coalesce(p_points, 0), 0)::numeric, 2);
  v_points numeric(12, 2);
  v_sale_total numeric(12, 2) := round(greatest(coalesce(p_sale_total, 0), 0)::numeric, 2);
begin
  if p_order_id is null then raise exception 'Order is required for loyalty reversal.'; end if;
  if p_member_id is null then raise exception 'Loyalty member is required for reversal.'; end if;

  select * into v_member
  from public.loyalty_members
  where id = p_member_id
  for update;
  if not found then raise exception 'Loyalty member was not found.'; end if;

  -- Award RPCs lock the member before the order. Keep the same order here so
  -- simultaneous sales and refunds cannot deadlock each other.
  select * into v_order
  from public.orders
  where id = p_order_id
  for update;
  if not found then raise exception 'Order was not found for loyalty reversal.'; end if;

  v_points := least(greatest(coalesce(v_order.loyalty_points_awarded, 0), 0), v_requested_points);
  if v_points <= 0 then return v_member; end if;

  update public.loyalty_members
  set "Points balance" = round(greatest(coalesce("Points balance", 0) - v_points, 0)::numeric, 2),
      "Available points" = round(greatest(coalesce("Available points", 0) - v_points, 0)::numeric, 2),
      "Total spent" = round(greatest(coalesce("Total spent", 0) - v_sale_total, 0)::numeric, 2)
  where id = p_member_id
  returning * into v_member;

  update public.orders
  set loyalty_points_awarded = round(greatest(coalesce(loyalty_points_awarded, 0) - v_points, 0)::numeric, 2)
  where id = p_order_id;

  return v_member;
end;
$function$

CREATE OR REPLACE FUNCTION public.touch_voucher_campaigns_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_loyalty_members_available_to_vouchers()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- prevent recursion because ensure_vouchers_for_member updates loyalty_members
  IF pg_trigger_depth() > 1 THEN
    RETURN NEW;
  END IF;

  PERFORM public.ensure_vouchers_for_member(NEW.id);
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_loyalty_members_points_to_vouchers()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  new_pts numeric;
  old_pts numeric;
begin
  if pg_trigger_depth() > 1 then
    return new;
  end if;

  if tg_op = 'INSERT' then
    perform public.ensure_vouchers_for_member(new.id);
    return new;
  end if;

  new_pts := coalesce((new."Available points")::numeric, 0);
  old_pts := coalesce((old."Available points")::numeric, 0);

  if new_pts <> old_pts then
    perform public.ensure_vouchers_for_member(new.id);
  end if;

  return new;
end;
$function$
